#if !FLUIDCACHING_COMPILE
// <autogenerated />
#pragma warning disable
#endif

#nullable enable

using System;
using System.Collections;
using System.Collections.Generic;
using System.Threading;

namespace FluidCaching;

#if !FLUIDCACHING_COMPILE
[global::Microsoft.CodeAnalysis.Embedded]
[global::System.Diagnostics.DebuggerNonUserCode]
#endif
internal sealed class LifespanManager<T> : IEnumerable<Node<T>>
    where T : class
{
    /// <summary>
    /// The number of bags which should be enough to store the requested capacity of items. The heuristic is that each
    /// bag should contain about 5% of the capacity.
    /// </summary>
    private const int PreferredNrOfBags = 20;

    /// <summary>
    /// Numbers of bags to keep open as a buffer when the minimum age forces more items to be there than the capacity allows.
    /// </summary>
    private const int EmptyBagsBuffer = 5;

    /// <summary>
    /// If the current bag index exceeds this number, the cache is cleared to prevent an overflow.
    /// </summary>
    private const int MaxBagIndex = 1000000;

    /// <summary>
    /// No item should be kept in the cache for more than this amount, irrespective of the consumer-provided max age.
    /// </summary>
    private readonly TimeSpan maxMaxAge = TimeSpan.FromHours(12);

    /// <summary>
    /// Maximum interval at which we want to do a validity check.
    /// </summary>
    private readonly TimeSpan maxInterval = TimeSpan.FromMinutes(3);

    private readonly FluidCache<T> owner;
    private readonly TimeSpan minAge;
    private readonly GetNow getNow;
    private readonly TimeSpan maxAge;
    private readonly TimeSpan validityCheckInterval;
    private readonly int bagItemLimit;
    private readonly OrderedAgeBagCollection<T> bags;

    private readonly object syncObject = new();

    private AgeBag<T>? currentBag;
    private DateTime nextValidityCheck;
    private int currentBagIndex;
    private int oldestBagIndex;

    /// <summary>
    /// The number of items added to the current bag. Is a field so that it can be updated through <see cref="Interlocked"/>.
    /// </summary>
#pragma warning disable SA1401 // Fields should be private
    internal int ItemsInCurrentBag;
#pragma warning restore SA1401

    public LifespanManager(FluidCache<T> owner, int capacity, TimeSpan minAge, TimeSpan maxAge, GetNow getNow)
    {
        this.owner = owner;
        this.minAge = minAge;
        this.getNow = getNow;

        this.maxAge = TimeSpan.FromMilliseconds(Math.Min(maxAge.TotalMilliseconds, maxMaxAge.TotalMilliseconds));

        validityCheckInterval =
            TimeSpan.FromMilliseconds(Math.Min(maxAge.TotalMilliseconds, maxInterval.TotalMilliseconds));

        bagItemLimit = Math.Max(capacity / PreferredNrOfBags, 1);

        int nrTimeSlices = (int)(maxMaxAge.TotalMilliseconds / maxInterval.TotalMilliseconds);

        // NOTE: Based on 240 time slices + 20 bags for ItemLimit + 5 bags empty buffer
        int nrBags = nrTimeSlices + PreferredNrOfBags + EmptyBagsBuffer;
        bags = new OrderedAgeBagCollection<T>(nrBags);

        Stats = new CacheStats(capacity, nrBags, bagItemLimit, minAge, this.maxAge, validityCheckInterval);

        OpenBag(0);
    }

    /// <summary>
    /// Gets the bag that receives new or touched items. Is never <see langword="null"/> after construction.
    /// </summary>
    public AgeBag<T> CurrentBag => currentBag!;

    public IsValid? ValidateCache { get; set; }

    public CacheStats Stats { get; }

    public int CurrentBagIndex
    {
        get => currentBagIndex;
        set
        {
            currentBagIndex = value;
            Stats.RegisterRawBagIndexes(oldestBagIndex, currentBagIndex);
        }
    }

    private int OldestBagIndex
    {
        get => oldestBagIndex;
        set
        {
            oldestBagIndex = value;
            Stats.RegisterRawBagIndexes(oldestBagIndex, currentBagIndex);
        }
    }

    private bool RequiresCleanup => (ItemsInCurrentBag > bagItemLimit) || (getNow() > nextValidityCheck);

    private bool HasProcessedAllBags => OldestBagIndex == CurrentBagIndex;

    private bool AlmostOutOfBags => (CurrentBagIndex - OldestBagIndex) > (bags.Count - EmptyBagsBuffer);

    /// <summary>
    /// Checks to see if cache is still valid and if the lifespan manager needs to do maintenance.
    /// </summary>
    public void CheckValidity()
    {
        // NOTE: We are using Monitor.TryEnter() because it does not wait for a lock. If the lock is currently held,
        // then skip and let the next Touch perform the cleanup.
        if (RequiresCleanup && TryEnterLock())
        {
            try
            {
                if (RequiresCleanup)
                {
                    // If the cache is no longer valid, throw the contents away and start over, else clean up old items
                    if (CurrentBagIndex > MaxBagIndex || (ValidateCache is not null && !ValidateCache()))
                    {
                        owner.Clear();
                    }
                    else
                    {
                        CleanUp(getNow());
                    }
                }
            }
            finally
            {
                ExitLock();
            }
        }
    }

    private bool TryEnterLock()
    {
        return Monitor.TryEnter(syncObject);
    }

    private void ExitLock()
    {
        Monitor.Exit(syncObject);
    }

    /// <summary>
    /// Remove old items or items beyond capacity from the lifespan manager allowing them to be garbage collected.
    /// </summary>
    /// <remarks>
    /// Since we do not physically move items when touched we must check items in bag to determine if they should
    /// be deleted or moved. Also items that were removed by setting value to null get removed now. Removing
    /// an item from the lifespan manager allows it to be garbage collected. If a removed item is retrieved by index prior
    /// to GC then it will be re-added to the lifespan manager.
    /// </remarks>
    private void CleanUp(DateTime now)
    {
        lock (syncObject)
        {
            int itemsAboveCapacity = Stats.Current - Stats.Capacity;
            AgeBag<T> bag = bags[OldestBagIndex];

            while (!HasProcessedAllBags && (AlmostOutOfBags || BagNeedsCleaning(bag, itemsAboveCapacity, now)))
            {
                itemsAboveCapacity = CleanBag(bag, itemsAboveCapacity);

                ++OldestBagIndex;
                bag = bags[OldestBagIndex];
            }

            ++CurrentBagIndex;
            OpenBag(CurrentBagIndex);

            EnsureIndexIsValid();
        }
    }

    private static int CleanBag(AgeBag<T> bag, int itemsAboveCapacity)
    {
        Node<T>? node = bag.First;
        bag.First = null;

        while (node is not null)
        {
            Node<T>? nextNode = node.Next;

            node.Next = null;
            if (node.Value is not null && node.Bag is not null)
            {
                if (node.Bag == bag)
                {
                    // Item has not been touched since bag was closed, so remove it from the lifespan manager
                    --itemsAboveCapacity;
                    node.RemoveFromCache();
                }
                else
                {
                    // Item has been touched and should be moved to correct age bag now
                    node.Next = node.Bag.First;
                    node.Bag.First = node;
                }
            }

            node = nextNode;
        }

        return itemsAboveCapacity;
    }

    private bool BagNeedsCleaning(AgeBag<T> bag, int itemsAboveCapacity, DateTime now)
    {
        return bag.HasExpired(maxAge, now) || (itemsAboveCapacity > 0 && bag.HasReachedMinimumAge(minAge, now));
    }

    private void EnsureIndexIsValid()
    {
        // If indexes are getting too big, it's time to rebuild them
        if (Stats.RequiresRebuild)
        {
            foreach (IIndexManagement<T> index in owner.Indexes)
            {
                Stats.MarkAsRebuild(index.RebuildIndex());
            }
        }
    }

    /// <summary>
    /// Remove all items from the lifespan manager and reset.
    /// </summary>
    public void Clear()
    {
        lock (syncObject)
        {
            bags.Empty();

            Stats.Reset();

            // Reset age bags
            OldestBagIndex = 0;
            OpenBag(0);
        }
    }

    /// <summary>
    /// Ready a new current age bag for use and close the previous one.
    /// </summary>
    private void OpenBag(int bagNumber)
    {
        lock (syncObject)
        {
            DateTime now = getNow();

            // Close last age bag
            if (currentBag is not null)
            {
                currentBag.StopTime = now;
            }

            // Open new age bag for next time slice
            CurrentBagIndex = bagNumber;

            AgeBag<T> newBag = bags[CurrentBagIndex];
            newBag.StartTime = now;
            newBag.First = null;

            currentBag = newBag;

            // Reset counters for CheckValidity()
            nextValidityCheck = now.Add(validityCheckInterval);
            ItemsInCurrentBag = 0;
        }
    }

    /// <summary>
    /// Create item enumerator.
    /// </summary>
    IEnumerator IEnumerable.GetEnumerator()
    {
        return GetEnumerator();
    }

    /// <summary>
    /// Create item enumerator.
    /// </summary>
    public IEnumerator<Node<T>> GetEnumerator()
    {
        for (int bagNumber = CurrentBagIndex; bagNumber >= OldestBagIndex; --bagNumber)
        {
            AgeBag<T> bag = bags[bagNumber];

            // If bag.First is null then the bag is empty or being cleaned up, so skip it!
            for (Node<T>? node = bag.First; node is not null && bag.First is not null; node = node.Next)
            {
                if (node.Value is not null)
                {
                    yield return node;
                }
            }
        }
    }

    public Node<T>? AddToHead(Node<T> node)
    {
        lock (syncObject)
        {
            Node<T>? next = CurrentBag.First;
            CurrentBag.First = node;

            Stats.RegisterMiss();

            return next;
        }
    }

    public void UnregisterFromLifespanManager()
    {
        Stats.UnregisterItem();
    }
}
